{"expected_revision_id": "04e7536d-29aa-4681-bdbe-d6c397ad2d2f", "source": "module counter (
    input  wire       clk,
    input  wire       rst,
    output reg  [3:0] count
);

    always @(posedge clk) begin
        if (rst)
            count <= 4'b0000;
        else
            count <= count + 4'b0001;
    end

endmodule
